def note_rank(note):
    searchable = (note.get('title', '') + ' ' + note.get('content', '')).lower()
    is_dinner = int('dinner' in searchable)
    is_yesterday = int(note.get('created_at', '')[:10] == yesterday_date or note.get('updated_at', '')[:10] == yesterday_date)
    is_work_related = int('work' in searchable or 'coworker' in searchable or 'colleague' in searchable)
    return (is_dinner, is_yesterday, is_work_related, note.get('updated_at', ''), note.get('created_at', ''))
selected_dinner_note = max(dinner_note_details, key=note_rank)
def normalized_words(value):
    return ' '.join(''.join(ch.lower() if ch.isalnum() else ' ' for ch in value).split())
first_name_counts = {}
for contact in coworkers:
    first = normalized_words(contact.get('first_name', ''))
    first_name_counts[first] = first_name_counts.get(first, 0) + 1
def positive_numbers(value):
    values = []
    current = ''
    for ch in value:
        if ch.isdigit() or ch in '.,':
            current += ch
        else:
            if any(c.isdigit() for c in current):
                try:
                    number = float(current.replace(',', ''))
                    if number > 0:
                        values.append(number)
                except ValueError:
                    pass
            current = ''
    if any(c.isdigit() for c in current):
        try:
            number = float(current.replace(',', ''))
            if number > 0:
                values.append(number)
        except ValueError:
            pass
    return values
note_segments = [segment.strip() for segment in selected_dinner_note['content'].replace('\r', '\n').replace(';', '\n').split('\n') if segment.strip()]
shares_by_email = {}
share_evidence = []
for segment in note_segments:
    segment_lower = segment.lower()
    padded_words = ' ' + normalized_words(segment) + ' '
    matched_contacts = []
    for contact in coworkers:
        email = contact.get('email', '').lower()
        first = normalized_words(contact.get('first_name', ''))
        full = normalized_words(contact.get('first_name', '') + ' ' + contact.get('last_name', ''))
        email_match = bool(email and email in segment_lower)
        full_match = bool(full and (' ' + full + ' ') in padded_words)
        unique_first_match = bool(first and first_name_counts.get(first) == 1 and (' ' + first + ' ') in padded_words)
        if email_match or full_match or unique_first_match:
            matched_contacts.append(contact)
    if len(matched_contacts) == 1:
        amount_source = segment[segment.find('$'):] if '$' in segment else segment
        numbers = positive_numbers(amount_source)
        if numbers:
            amount = numbers[0] if '$' in segment else numbers[-1]
            email = matched_contacts[0]['email'].lower()
            if email in shares_by_email and abs(shares_by_email[email] - amount) >= 0.005:
                raise RuntimeError('Conflicting dinner-share amounts for ' + email)
            shares_by_email[email] = amount
            share_evidence.append({'name': matched_contacts[0]['first_name'] + ' ' + matched_contacts[0]['last_name'], 'email': email, 'amount': amount})
if not shares_by_email:
    raise RuntimeError('No coworker share amounts could be mapped from the selected note')
print({'selected_note_id': selected_dinner_note['note_id'], 'parsed_shares': share_evidence})

